### 3.3 Conditional Logic (Runtime Resolution)

```javascript
// Runtime resolver — not a static stylesheet
class SpoonResolver {
  constructor(dialValue, deviceContext) {
    this.dial = Math.max(0, Math.min(5, Math.round(dialValue)));
    this.device = deviceContext; // { width, reducedMotion, highContrast }
  }

  get(tokenName) {
    let value = tokens.semantic[tokenName][this.dial];

    // Overrides: device context takes precedence over dial
    if (this.device.reducedMotion && tokenName === 'motion.duration') {
      return '0ms';
    }
    if (this.device.highContrast && tokenName === 'text.primary.contrast') {
      return '7.0';
    }

    // Derived: essential action is always visible at dial <= 1
    if (tokenName === 'layout.essentialAction.visible') {
      return this.dial <= 1 ? true : true; // always visible
    }

    // Derived: only one action at dial 0–1
    if (tokenName === 'layout.essentialAction.only') {
      return this.dial <= 1;
    }

    return value;
  }

  // Transition guard: never jump more than 1 level per 500ms
  transitionTo(newDial) {
    const diff = Math.abs(newDial - this.dial);
    if (diff > 1) {
      // Animate through intermediate levels
      this.animateThrough(newDial, 500);
    }
  }
}
```

